1	// parent: the order process of SPEC-E (E8). It routes each event to the sub-workflow that owns it, keeps the order's
2	// record in its own state (fulfilment statuses, cleared or ended, the collection reports of R6.2) and asks the
3	// modules for what the rules require. Modules keep their own state; the parent reads only their outputs.
4	
5	const TERMINAL = ['completed', 'failed', 'cancelled'];
6	const COLLECTED = ['collected', 'inTransit', 'delivered'];           // S7: reports that prove collection
7	const PHASE_STATUS = { reserving: 'processing', charging: 'processing', shipping: 'processing', shipped: 'processing',
8	  dispatched: 'dispatched', completed: 'completed', failed: 'failed', cancelled: 'cancelled' };
9	
10	const isObj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
11	const ms = s => Date.parse(s);
12	const norm = s => String(s ?? '').trim().replace(/^#/, '').trim().toUpperCase();     // SPEC §3.1
13	const jsonOf = f => (typeof f === 'string' ? JSON.parse(f) : (f ?? null));
14	const rowsOf = r => (Array.isArray(r) ? r : (isObj(r) && Array.isArray(r.rows) ? r.rows : []));
15	
16	// The API may rename a field: api/<system>.schema.json in ctx.files shows the current names, so send those.
17	const fitNorm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
18	function fitArgs(e, files) {
19	  const props = jsonOf(files?.[`api/${e.system}.schema.json`])?.ops?.[e.op]?.args?.properties;
20	  if (!props || !isObj(e.args)) return e;
21	  const names = Object.keys(props);
22	  const keys = Object.keys(e.args);
23	  const extra = keys.filter(k => !names.includes(k));
24	  const missing = names.filter(n => !keys.includes(n));
25	  const renamed = {};
26	  for (const k of extra) renamed[k] = names.find(n => fitNorm(n) === fitNorm(k)) ?? (extra.length === 1 && missing.length === 1 ? missing[0] : k);
27	  const args = {};
28	  for (const k of keys) args[renamed[k] ?? k] = e.args[k];
29	  return { ...e, args };
30	}
31	
32	// A lookup table from a master or rulebook file: a list of rows, or an object keyed by the key itself.
33	function mapOf(x, keys, vals) {
34	  const out = {};
35	  const list = Array.isArray(x) ? x : (isObj(x) ? Object.values(x).find(Array.isArray) : null);
36	  if (list) {
37	    for (const r of list) {
38	      const k = keys.map(n => r?.[n]).find(v => v !== undefined);
39	      const v = vals.map(n => r?.[n]).find(z => z !== undefined);
40	      if (k !== undefined && v !== undefined) out[k] = v;
41	    }
42	  } else if (isObj(x)) {
43	    for (const [k, v] of Object.entries(x)) out[k] = isObj(v) ? vals.map(n => v[n]).find(z => z !== undefined) : v;
44	  }
45	  return out;
46	}
47	
48	// R1.3: the published edition with the latest effectiveFrom on or before the date of p (Amsterdam local date).
49	function editionAt(ctx, placedAt) {
50	  const day = String(placedAt).slice(0, 10);
51	  let best = null;
52	  for (const k of Object.keys(ctx.files)) {
53	    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(k);
54	    if (!m) continue;
55	    const from = String(jsonOf(ctx.files[k])?.effectiveFrom ?? '');
56	    if (from && from <= day && (!best || from > best.from)) best = { dir: m[1], from };
57	  }
58	  return best?.dir ?? null;
59	}
60	
61	function rulesOf(ctx, ed) {
62	  const f = p => jsonOf(ctx.files[p]);
63	  return {
64	    fees: mapOf(f(`rulebook/${ed}/shipping-fees.json`), ['location', 'locationId'], ['feeMinor']),
65	    codes: mapOf(f(`rulebook/${ed}/carrier-codes.json`), ['code'], ['meaning']),
66	    policy: f(`rulebook/${ed}/policy.json`) ?? {},
67	  };
68	}
69	
70	// Which event this is, from its payload (routing is by channel; the business kind is read here).
71	function kindOf(ev) {
72	  const p = ev.payload ?? {};
73	  if (ev.type === 'effect.result' || ev.type === 'timer.fired' || String(ev.type).startsWith('humanTask.')) return 'owned';
74	  if (p.orderId !== undefined && Array.isArray(p.items)) return 'placed';
75	  if (p.orderRef !== undefined && p.action !== undefined) return 'customer';
76	  if (p.fulfilmentRef !== undefined && p.code !== undefined) return 'carrier';
77	  return 'other';
78	}
79	
80	export function tick(input, ctx) {
81	  const st = input.state ?? { o: null };
82	  const me = input.instance;
83	  let subject = st.o?.id ?? null;
84	
85	  // --- a new instance started by an inbound message (§3.2): merge it into its order's case, or start one
86	  const openFor = oid => rowsOf(ctx.instances({ subject: oid })).map(x => (typeof x === 'string' ? x : x?.instance))
87	    .filter(x => x && x !== me);
88	
89	  // --- the order record: st.o = { id, customerId, currency, p, ed, email, reviewHours, actionHours, fs, coll, phase, cleared, ended }
90	  const o = () => st.o;
91	
92	  function startOrder(ev) {
93	    const p = ev.payload;
94	    const oid = norm(p.orderId);
95	    const ed = editionAt(ctx, p.placedAt);
96	    const r = rulesOf(ctx, ed);
97	    const cust = mapOf(jsonOf(ctx.files['master/customers.json']), ['customerId', 'id'], ['email']);
98	    const cat = mapOf(jsonOf(ctx.files['master/catalog.json']), ['sku'], ['unitPriceMinor']);
99	    const prices = {};
100	    for (const it of p.items ?? []) if (cat[it.sku] !== undefined) prices[it.sku] = cat[it.sku];
101	    st.o = { id: oid, customerId: p.customerId, currency: p.currency, p: p.placedAt, ed, email: cust[p.customerId] ?? '',
102	      reviewHours: r.policy.fraudReviewHours, actionHours: r.policy.customerActionHours, fs: {}, coll: {}, phase: 'allocating',
103	      cleared: false, ended: null };
104	    ctx.call('intake', oid, { op: 'place', orderId: oid, customerId: p.customerId, placedAt: p.placedAt, currency: p.currency,
105	      items: p.items, prices, fees: r.fees });
106	    subject = oid;
107	  }
108	
109	  // R2.2: a review task opens (its deadline is fixed from this first task)
110	  function openReview(at) {
111	    const x = o();
112	    if (x.ended || x.cleared || x.phase === 'review') return;
113	    x.phase = 'review';
114	    ctx.call('review', x.id, { op: 'open', orderId: x.id, reviewHours: x.reviewHours, at });
115	  }
116	
117	  // R3.1 or R4.1: the order is cleared at t; with unavailable items the customer is asked first
118	  function clearAt() {
119	    const x = o();
120	    if (x.ended || x.cleared) return;
121	    x.cleared = true;
122	    if (Object.values(x.fs).some(f => !f.avail)) {
123	      x.phase = 'waiting';
124	      ctx.call('wait', x.id, { op: 'arm', orderId: x.id, p: x.p, customerActionHours: x.actionHours, email: x.email,
125	        fulfilments: Object.entries(x.fs).map(([fulfilmentId, f]) => ({ fulfilmentId, available: f.avail })) });
126	    } else startProcessing();
127	  }
128	
129	  // R4.1: the order and every available fulfilment become processing; each fulfilment's saga starts
130	  function startProcessing() {
131	    const x = o();
132	    x.phase = 'processing';
133	    ctx.call('close', x.id, { op: 'processing', orderId: x.id });
134	    for (const [fid, f] of Object.entries(x.fs)) {
135	      if (!f.avail || f.status !== 'pending') continue;
136	      f.status = 'processing';
137	      ctx.call('fulfil', `${x.id}.${fid}`, { op: 'start', orderId: x.id, fid, location: f.loc, customerId: x.customerId,
138	        email: x.email, currency: x.currency, amountMinor: f.amt, items: f.items });
139	    }
140	  }
141	
142	  // R6.1, R6.2, R6.4, S15: the order is cancelled: started fulfilments compensated, the rest set cancelled, the order too
143	  function cancelOrder(reason, at) {
144	    const x = o();
145	    if (x.ended) return;
146	    x.ended = 'cancelled';
147	    x.phase = 'ended';
148	    for (const [fid, f] of Object.entries(x.fs)) {
149	      if (TERMINAL.includes(f.status)) continue;
150	      if (f.status === 'processing') {
151	        const r = ctx.call('fulfil', `${x.id}.${fid}`, { op: 'compensate', reason: 'cancelled' });
152	        f.status = r?.phase ?? 'cancelled';
153	      } else {
154	        f.status = 'cancelled';
155	        ctx.emit(fitArgs({ key: `fs-cancel-${fid}`, system: 'orders', op: 'setStatus', args: { orderId: x.id, fulfilmentId: fid, status: 'cancelled' } }, ctx.files));
156	      }
157	    }
158	    ctx.call('close', x.id, { op: 'cancel', orderId: x.id, email: x.email, reason, at });
159	  }
160	
161	  // R6.2: a collection report (meaning collected, inTransit or delivered) at or before t proves collection (S7)
162	  const collectedBy = at => Object.values(o().coll).some(r => ms(r) <= ms(at));
163	
164	  // R4.5: once every fulfilment has ended, the order's outcome
165	  function maybeOutcome() {
166	    const x = o();
167	    if (x.ended || x.phase !== 'processing') return;
168	    const statuses = Object.values(x.fs).map(f => f.status);
169	    if (!statuses.every(s => TERMINAL.includes(s))) return;
170	    const r = ctx.call('close', x.id, { op: 'outcome', orderId: x.id, statuses });
171	    if (r?.phase === 'final') { x.ended = r.status; x.phase = 'ended'; }
172	  }
173	
174	  function applyFulfil(fid, out) {
175	    const f = o().fs[fid];
176	    if (!f) return;
177	    if (PHASE_STATUS[out?.phase]) f.status = PHASE_STATUS[out.phase];
178	    maybeOutcome();
179	  }
180	
181	  // Results, timers and human-task events: delivered to the module instance that caused them
182	  function deliverOwned(ev) {
183	    const x = o();
184	    const own = ctx.ownerOf(ev);
185	    if (!own || !x) return;
186	    const out = ctx.deliver(ev) ?? {};
187	    if (own.module === 'intake') {
188	      if (out.phase === 'recorded') {
189	        for (const f of out.fulfilments) x.fs[f.fulfilmentId] = { loc: f.location, amt: f.amountMinor, items: f.items,
190	          avail: f.available, status: f.available ? 'pending' : 'unavailable' };
191	        x.phase = 'checking';
192	      }
193	      if (out.phase === 'verdict') {
194	        if (out.verdict === 'pass') clearAt();                              // R2.1: cleared at p
195	        else if (out.verdict === 'reject') cancelOrder('fraud', ev.at);      // R2.1: cancel within 120 min of p
196	        else openReview(ev.at);                                              // R2.1: review
197	      }
198	    } else if (own.module === 'review') {
199	      if (out.phase === 'approved') clearAt();
200	      else if (out.phase === 'rejected') cancelOrder('fraud', out.at ?? ev.at);
201	      else if (out.phase === 'timed-out') cancelOrder('fraud-review-timeout', out.at ?? ev.at);
202	    } else if (own.module === 'wait') {
203	      if (out.timedOut) {
204	        for (const f of Object.values(x.fs)) f.status = 'cancelled';
205	        x.ended = 'timedOut';
206	        x.phase = 'ended';
207	      }
208	    } else if (own.module === 'fulfil') {
209	      applyFulfil(own.key.slice(x.id.length + 1), out);
210	    } else if (own.module === 'close' && out.phase === 'final') {
211	      x.ended = out.status;
212	      x.phase = 'ended';
213	    }
214	  }
215	
216	  // §3.3 customer actions (S5, S8, S11, R3.2, R6.2, R6.3, R6.4)
217	  function onCustomer(ev) {
218	    const x = o();
219	    const p = ev.payload;
220	    if (!x || x.id !== norm(p.orderRef) || x.ended) return;
221	    if (p.action === 'cancel') {
222	      if (!x.cleared) return cancelOrder('customer', ev.at);                // R6.4: fraud review open
223	      if (x.phase === 'waiting') {
224	        const w = ctx.call('wait', x.id, { op: 'action', at: ev.at, action: 'cancel' });
225	        if (w?.counted === 'cancel') cancelOrder('customer', ev.at);
226	        return;
227	      }
228	      if (x.phase === 'processing') {
229	        if (collectedBy(ev.at)) return ctx.call('close', x.id, { op: 'refuse', orderId: x.id, ref: ev.id, email: x.email });
230	        return cancelOrder('customer', ev.at);                              // R6.2
231	      }
232	      return;
233	    }
234	    if (p.action === 'amend' && x.phase === 'waiting') {
235	      const w = ctx.call('wait', x.id, { op: 'action', at: ev.at, action: 'amend' });
236	      if (w?.counted !== 'amend') return;
237	      for (const f of Object.values(x.fs)) if (!f.avail) f.status = 'cancelled';
238	      if (w.nothingAvailable) return cancelOrder('nothing-available', ev.at);   // R3.2
239	      startProcessing();                                                       // ready at a (R4)
240	    }
241	  }
242	
243	  // §3.3 carrier messages (R4.4): routed to the fulfilment by its fulfilmentRef
244	  function onCarrier(ev) {
245	    const x = o();
246	    const p = ev.payload;
247	    if (!x || !x.fs[p.fulfilmentRef]) return;
248	    const meaning = rulesOf(ctx, x.ed).codes[p.code] ?? 'info';              // a code not listed is info
249	    if (COLLECTED.includes(meaning) && (!x.coll[p.fulfilmentRef] || ms(p.reportedAt) < ms(x.coll[p.fulfilmentRef]))) {
250	      x.coll[p.fulfilmentRef] = p.reportedAt;
251	    }
252	    const out = ctx.call('fulfil', `${x.id}.${p.fulfilmentRef}`, { op: 'carrier', meaning, reportedAt: p.reportedAt });
253	    applyFulfil(p.fulfilmentRef, out);
254	  }
255	
256	  // The first tick of an instance started by a message: placed orders start one; anything else merges into the open
257	  // case of its order or closes (S11: an action that names no order yet changes nothing)
258	  function freshMessage(k, ev) {
259	    const p = ev.payload;
260	    const oid = k === 'placed' ? norm(p.orderId) : k === 'customer' ? norm(p.orderRef)
261	      : rowsOf(ctx.query('orders.fulfilments', { where: { fulfilmentId: p.fulfilmentRef }, limit: 1 }))[0]?.orderId;
262	    const target = oid ? openFor(norm(oid))[0] : undefined;
263	    if (target) return { decisions: { subject: norm(oid) }, state: null, merge: { into: target } };
264	    if (k === 'placed') { startOrder(ev); return null; }
265	    return { decisions: { subject: oid ? norm(oid) : null }, state: null, close: true };
266	  }
267	
268	  for (const ev of input.events ?? []) {
269	    const k = kindOf(ev);
270	    if (k === 'owned') { deliverOwned(ev); continue; }
271	    if (!st.o && (k === 'placed' || k === 'customer' || k === 'carrier')) {
272	      const early = freshMessage(k, ev);
273	      if (early) return early;
274	      continue;
275	    }
276	    if (k === 'customer') onCustomer(ev);
277	    else if (k === 'carrier') onCarrier(ev);
278	    // a repeated placed order (R1.4) and any other message: no effect
279	  }
280	  return { decisions: { subject }, state: st };
281	}
282

