1	// wait: R3 customer action on unavailable items. Keys: 'status' (order customerActionRequired), 'notice', 'deadline'
2	// (timer at D+1 min, so an action at exactly D still wins, S1), 'fcancel-<id>' and 'order-timedout' at the timeout.
3	// The parent calls op 'arm' when the order is cleared with an unavailable fulfilment, op 'action' for each customer
4	// action that reaches the order, and op 'timeout' when the deadline timer fires.
5	
6	const addMin = (iso, m) => new Date(Date.parse(iso) + m * 60000).toISOString();
7	
8	function stepRaw(input, ctx) {
9	  const st = ctx.state;
10	  if (input.op === 'arm') {
11	    if (st) return { output: { phase: st.phase } };
12	    const D = addMin(input.p, input.customerActionHours * 60);     // S1: anchored at p, not at the clearance
13	    const next = { orderId: input.orderId, email: input.email, D, phase: 'waiting', fulfilments: input.fulfilments };
14	    return {
15	      state: next,
16	      effects: [
17	        { key: 'status', system: 'orders', op: 'setStatus', args: { orderId: input.orderId, fulfilmentId: null, status: 'customerActionRequired' } },
18	        { key: 'notice', system: 'notify', op: 'send', args: { to: input.email, about: input.orderId, template: 'action-required', text: 'Some items are unavailable: amend or cancel your order.' } },
19	      ],
20	      obligations: { upsert: [{ id: 'deadline', kind: 'customerActionDeadline', anchor: input.p, dueAt: addMin(D, 1), onDue: 'timeout' }] },
21	      output: { phase: 'waiting', D },
22	    };
23	  }
24	  if (!st) return { output: { phase: 'none' } };
25	  if (input.op === 'action') {
26	    // R3.2: the first amend or cancel at or before D counts; later ones change nothing (S5, S8)
27	    if (st.phase !== 'waiting') return { output: { counted: null, phase: st.phase } };
28	    if (Date.parse(input.at) > Date.parse(st.D)) return { output: { counted: null, phase: 'late' } };
29	    const available = st.fulfilments.filter(f => f.available);
30	    if (input.action === 'cancel') {
31	      return { state: { ...st, phase: 'customer' }, obligations: { cancel: ['deadline'] }, output: { counted: 'cancel', at: input.at } };
32	    }
33	    // amend: every unavailable fulfilment cancelled (within 60 min of the amend); the rest continue
34	    const unavailable = st.fulfilments.filter(f => !f.available);
35	    const effects = unavailable.map(f => ({ key: `fcancel-${f.fulfilmentId}`, system: 'orders', op: 'setStatus',
36	      args: { orderId: st.orderId, fulfilmentId: f.fulfilmentId, status: 'cancelled' } }));
37	    return {
38	      state: { ...st, phase: 'amended' }, effects, obligations: { cancel: ['deadline'] },
39	      output: { counted: 'amend', at: input.at, nothingAvailable: available.length === 0, available: available.map(f => f.fulfilmentId) },
40	    };
41	  }
42	  if (input.op === 'timeout') return timeout(st);
43	  return { output: { phase: st.phase } };
44	}
45	
46	// The deadline timer (fires at D+1 min) and the parent's explicit 'timeout' call share this.
47	function timeout(st) {
48	  if (st.phase !== 'waiting') return { output: { timedOut: false, phase: st.phase } };
49	  // nothing counted by D: every fulfilment cancelled, the order timedOut, the customer told (R3.2)
50	  const effects = st.fulfilments.map(f => ({ key: `fcancel-${f.fulfilmentId}`, system: 'orders', op: 'setStatus',
51	    args: { orderId: st.orderId, fulfilmentId: f.fulfilmentId, status: 'cancelled' } }));
52	  effects.push({ key: 'order-timedout', system: 'orders', op: 'setStatus', args: { orderId: st.orderId, fulfilmentId: null, status: 'timedOut' } });
53	  effects.push({ key: 'notice-timeout', system: 'notify', op: 'send', args: { to: st.email, about: st.orderId, template: 'order-timed-out', text: 'Your order timed out.' } });
54	  return { state: { ...st, phase: 'timedOut' }, effects, output: { timedOut: true, phase: 'timedOut' } };
55	}
56	
57	// The timer arrives here (routed to this instance by its name).
58	function onEventRaw(event, ctx) {
59	  const st = ctx.state;
60	  if (!st) return { output: { phase: 'none' } };
61	  if (event?.type === 'timer.fired') return timeout(st);
62	  return { output: { phase: st.phase } };
63	}
64	
65	// The API may rename a field: api/<system>.schema.json in ctx.files shows the current names, so send those.
66	const fitNorm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
67	function fitArgs(e, files) {
68	  const sch = files?.[`api/${e.system}.schema.json`];
69	  const props = (typeof sch === 'string' ? JSON.parse(sch) : sch)?.ops?.[e.op]?.args?.properties;
70	  if (!props || e.args === null || typeof e.args !== 'object' || Array.isArray(e.args)) return e;
71	  const names = Object.keys(props);
72	  const keys = Object.keys(e.args);
73	  const extra = keys.filter(k => !names.includes(k));
74	  const missing = names.filter(n => !keys.includes(n));
75	  const renamed = {};
76	  for (const k of extra) renamed[k] = names.find(n => fitNorm(n) === fitNorm(k)) ?? (extra.length === 1 && missing.length === 1 ? missing[0] : k);
77	  const args = {};
78	  for (const k of keys) args[renamed[k] ?? k] = e.args[k];
79	  return { ...e, args };
