      const row = { fulfilmentId: f.fulfilmentId, location: f.location ?? null, items: (f.items ?? []).map(i => ({ sku: i.sku, qty: i.qty })), available: f.available !== false };
      return { ...row, amountMinor: priceFulfilment(row, st.prices, st.fees) };
